<script setup lang="ts">import {Run} from '../types/domain';import {scientific} from '../utils/format';defineProps<{run:Run}>();const hasLocks=(run:Run)=>Boolean(run.result?.locked||(run.locked_weights&&run.locked_weights.length));</script><template><div class="run-summary"><div><span class="eyebrow">{{run.result.library.code}} / FIXED ENDMEMBERS</span><h3>{{run.result.library.name}}</h3><p>{{run.result.samples.length}} 个混合样本 · {{run.result.endmembers.length}} 个端元 · {{run.result.library.wavelengths.length}} 波段</p><p v-if="hasLocks(run)" class="lock-summary-line">称量锁定 {{run.result.locked_weights?.length||run.locked_weights?.length||0}} 个端元<template v-if="run.result.lock_basis||run.lock_basis"> · 依据：{{run.result.lock_basis||run.lock_basis}}</template></p></div><div class="summary-number"><span>{{run.result.diagnostics.free_endmember_count!==undefined&&hasLocks(run)?'自由端元条件数':'增广条件数'}}</span><b>{{scientific(run.result.diagnostics.condition_number)}}</b><small>{{hasLocks(run)?'剩余自由度可辨识性':'满列秩 / 唯一解释先决'}}</small></div><div class="summary-number"><span>条件扰动</span><b>{{run.result.repeats}} <i>次</i></b><small>σ {{run.result.noise_sigma}} / 固定端元</small></div></div></template>
